import type { Plugin } from 'vite';
import type { Logger } from '../types.ts';
/**
 * This is a Vite plugin that blocks CSS imports in UI extensions.
 * In the dev server we warn the user, but allow the extension to build and be served.
 * In remote builds we throw an error so the extension cannot be built.
 *
 * @param args An object containing optional logger and onCssBlocked callback.
 */
declare const cssBlockingPlugin: ({ logger, onCssBlocked, }?: {
    logger?: Logger;
    onCssBlocked?: (message: string) => void;
}) => Plugin;
export default cssBlockingPlugin;
